196	// TestSetupSaysWhatIsUnavailableWhenNothingCanAnswer is the whole-run
197	// property. It used to assert exit 0 ("one component built, so the brain is
198	// worth keeping"), which main has since superseded: `setup --help` now states
199	// the contract outright -- setup exits 0 whenever the brain is QUERYABLE, and
200	// queryable means at least one of the semantic index, the seed baseline or the
201	// history index built. Session export is none of those.
202	//
203	// The half of this PR that stands is the other one, and it is what is asserted
204	// here: whatever the exit code, setup must not claim queryability it does not
205	// have, and must name what is missing.
206	func TestSetupSaysWhatIsUnavailableWhenNothingCanAnswer(t *testing.T) {
207		f := newSetupTestFixture(t, "s1")
208		rec := &recordedSetup{instantComponents: []setupComponent{
209			{Name: brainComponentSessions, State: "ok"},
210			{Name: brainComponentSeed, State: "failed", Detail: "dirty_worktree: refusing to seed uncommitted content"},
211			{Name: brainComponentSemantic, State: "failed", Detail: "dirty_worktree: refusing to index uncommitted content"},
212		}}
213		opts := defaultSetupOptions()
214		opts.noDaemon = true
215		opts.noBackfill = true
216	
217		out := &bytes.Buffer{}
218		err := runSetup(context.Background(), setupTestCommand(t, out, opts), f.opts, opts, f.repoDir, rec.steps(f))
219		if err == nil {
220			t.Fatalf("no index and no baseline is not a queryable brain, so setup must not exit 0:\n%s", out.String())
221		}
222		// The failure has to NAME both missing sources. "setup failed" alone sends
223		// the reader back to the output they already could not act on.
224		for _, want := range []string{"seed baseline", "code index"} {
225			if !strings.Contains(err.Error(), want) {
226				t.Fatalf("setup must name what is unavailable (%q): %v", want, err)
227			}
228		}
229		if strings.Contains(out.String(), "queryable now") {
230			t.Fatalf("setup claimed queryability with no index and no baseline:\n%s", out.String())
231		}
232	}
