278	// --- UX-27: one remedy for one dirty worktree -------------------------------
279	
280	// dirtySeedRetrievalStatus runs the REAL producer, so a remedy put back into
281	// the freshness axis is caught here rather than in a hand-written fixture.
282	func dirtySeedRetrievalStatus(t *testing.T) *brainStatusRetrieval {
283		t.Helper()
284		repoDir := t.TempDir()
285		runner := &fakeCommandRunner{responses: map[string]fakeCommandResponse{}}
286		live := brainLiveState{Branch: "main", Head: "58b0c54e", Dirty: true}
287		manifest := &exportManifest{Sources: &brainSources{
288			Seed: &seedSourceManifest{Commit: "58b0c54e", WorktreeMode: "commit", GeneratedAt: setupTestNow},
289		}}
290		// audit=false is the lightweight status path, which is the surface this
291		// test is about; the audit path is doctor's.
292		return buildBrainRetrievalStatus(context.Background(), runner, t.TempDir(), repoDir, manifest, live, false)
293	}
294	
295	func TestDirtyWorktreeCauseCarriesNoRemedyOfItsOwn(t *testing.T) {
296		t.Parallel()
297		status := dirtySeedRetrievalStatus(t)
298		axis := status.Freshness.Axes["seed"]
299		if axis.State != "dirty-unindexed" {
300			t.Fatalf("fixture did not reach the dirty-unindexed axis: %+v", axis)
301		}
302		if strings.Contains(axis.Detail, "--worktree") || strings.Contains(axis.Detail, "refresh") {
303			t.Fatalf("the cause must not offer a remedy; setupDirtyWorktreeHint owns it: %q", axis.Detail)
304		}
305		if !strings.Contains(axis.Detail, "committed HEAD") {
306			t.Fatalf("the cause must still say what is wrong: %q", axis.Detail)
307		}
308	}
309	
310	func TestDirtyWorktreeGetsExactlyOneRemedy(t *testing.T) {
311		t.Parallel()
312		report := statusFixtureReport(t, 0)
313		report.Live.Dirty = true
314		report.Semantic.Freshness = &staleReport{Severity: "ok", Axes: map[string]staleAxis{"store": {State: "ok"}}}
315		// ONLY the seed axis. The producer's fixture also raises docs=missing, and
316		// the two details together overrun statusCauseWidth -- which silently
317		// truncated the very text this test is about, so the first version of it
318		// could not fail. The axis itself still comes from the producer, so a
319		// remedy put back into it is still caught here.
320		seed := dirtySeedRetrievalStatus(t).Freshness.Axes["seed"]
321		report.Retrieval = &brainStatusRetrieval{Freshness: &staleReport{
322			Severity: "degraded",
323			Axes:     map[string]staleAxis{"seed": seed},
324		}}
325	
326		got := renderStatusShortPlain(t, report)
327		remedy := setupDirtyWorktreeHint(base.SetupBrainBinaryName)
328		if !strings.Contains(got, remedy) {
329			t.Fatalf("the verdict must carry the one remedy resolver's answer:\n%s", got)
330		}
331		// The resolver names --worktree exactly once. A second mention in the cause
332		// underneath is the contradiction this guards against.
333		if want, got2 := strings.Count(remedy, "--worktree"), strings.Count(got, "--worktree"); got2 != want {
334			t.Fatalf("a dirty tree must be answered once, found %d mentions of --worktree (resolver has %d):\n%s", got2, want, got)
335		}
336		if strings.Contains(got, "refresh with --worktree to include current changes") {
337			t.Fatalf("the cause is still offering its own, contradictory remedy:\n%s", got)
338		}
339		// Non-vacuity: the cause line must actually be on screen, or the count
340		// above is counting nothing.
341		if !strings.Contains(got, "seed=dirty-unindexed") || !strings.Contains(got, seed.Detail) {
342			t.Fatalf("the cause never reached the output, so nothing above was tested:\n%s", got)
343		}
344	}
345	
346	// TestStatusStatesTheDirtyRemedyExactlyOnce is UX-26 and UX-27 together. A
347	// dirty worktree refuses BOTH seed and semantic, so printing each failed
348	// component's hint put the same sentence on screen twice -- and the verdict
349	// underneath printed it a third time. Saying what failed and why must not
350	// become saying one remedy three times.
351	func TestStatusStatesTheDirtyRemedyExactlyOnce(t *testing.T) {
352		t.Parallel()
353		remedy := setupDirtyWorktreeHint(base.SetupBrainBinaryName)
354		report := statusFixtureReport(t, 0)
355		report.Live.Dirty = true
356		report.Semantic.Freshness = &staleReport{Severity: "ok", Axes: map[string]staleAxis{"store": {State: "ok"}}}
357		seed := dirtySeedRetrievalStatus(t).Freshness.Axes["seed"]
358		report.Retrieval = &brainStatusRetrieval{Freshness: &staleReport{
359			Severity: "degraded",
360			Axes:     map[string]staleAxis{"seed": seed},
361		}}
362		report.Onboarding.Components = []brainStatusComponent{
363			{Name: "seed", State: "failed", Detail: "dirty_worktree: refusing to seed uncommitted content without --worktree", Hint: remedy},
364			{Name: "semantic", State: "failed", Detail: "dirty_worktree: refusing to index uncommitted content without --worktree", Hint: remedy},
365		}
366	
367		got := renderStatusShortPlain(t, report)
368		if n := strings.Count(got, remedy); n != 1 {
369			t.Fatalf("one remedy, one appearance; found %d:\n%s", n, got)
370		}
371		// Non-vacuity: both failures are still reported, with their own reasons.
372		for _, want := range []string{"refusing to seed uncommitted content", "refusing to index uncommitted content"} {
373			if !strings.Contains(got, want) {
374				t.Fatalf("deduping the remedy must not drop a failure reason (%q):\n%s", want, got)
375			}
376		}
377	}
378	
379	// TestDirtyWorktreeRemedyNamesBothWaysOut: the resolver is the only place the
380	// reader is told what to do, so it has to name both -- the one that re-runs
381	// setup on a clean tree and the one that indexes the tree as it is.
382	func TestDirtyWorktreeRemedyNamesBothWaysOut(t *testing.T) {
383		t.Parallel()
384		remedy := setupDirtyWorktreeHint(base.SetupBrainBinaryName)
385		for _, want := range []string{"commit or stash", base.SetupBrainBinaryName + " setup", "refresh --worktree", "entire enable"} {
386			if !strings.Contains(remedy, want) {
387				t.Fatalf("the single remedy must name %q: %s", want, remedy)
388			}
389		}
390	}
391	
392	// Moving the remedy out of axis.Detail (so the short status would not print it
393	// twice) left `status --verbose` showing the cause with no way out: it renders
394	// Detail directly and never re-pairs the hint. Raised as a finding on this PR,
395	// and correct.
396	func TestVerboseAxesStillNameTheWayOut(t *testing.T) {
397		t.Parallel()
398		var buf bytes.Buffer
399		// The remedy now travels ON the axis, so the fixture carries it the way
400		// a producer does. Rendering it from the state alone is what left the
401		// JSON report -- which is what an agent and every script read -- holding
402		// a cause with no next step.
403		renderFreshnessAxes(&buf, map[string]staleAxis{
404			"seed": {
405				State:  dirtyUnindexedAxisState,
406				Detail: "seed and docs are based on committed HEAD",
407				Remedy: setupDirtyWorktreeHint("entire brain"),
408			},
409		})
410		line := buf.String()
411	
412		if !strings.Contains(line, "dirty-unindexed") {
413			t.Fatalf("fixture did not render the axis under test: %q", line)
414		}
415		for _, want := range []string{"--worktree", "commit or stash"} {
416			if !strings.Contains(line, want) {
417				t.Errorf("the verbose axis states a cause with no remedy; missing %q in: %s", want, line)
418			}
419		}
420	}
421	
422	// A healthy axis must not gain a dirty-worktree remedy it has no use for.
423	func TestACleanAxisGetsNoDirtyRemedy(t *testing.T) {
424		t.Parallel()
425		var buf bytes.Buffer
426		renderFreshnessAxes(&buf, map[string]staleAxis{"seed": {State: "current"}})
427		if strings.Contains(buf.String(), "--worktree") {
428			t.Fatalf("a clean axis was given the dirty-worktree remedy: %s", buf.String())
429		}
430	}
431	
432	// A dirty working tree fails BOTH seed and semantic — the common first run this
433	// release's own docs describe — and each failed component carries the identical
434	// hint, so the reader was told the same thing twice within six lines.
435	// status_render.go was given a dedup guard in this change; setup's own summary
436	// was missed. Raised as a finding on this PR, and correct.
437	func TestTheSetupSummaryStatesOneRemedyOnce(t *testing.T) {
438		t.Parallel()
439		hint := setupDirtyWorktreeHint("entire brain")
440		report := setupReport{
441			Instant: setupPhase{Components: []setupComponent{
442				{Name: "seed", State: "failed", Detail: "dirty_worktree: refusing to seed", Hint: hint},
443				{Name: "semantic", State: "failed", Detail: "dirty_worktree: refusing to index", Hint: hint},
444			}},
445		}
446		// Hints are PHASE DETAILS, not terse-block rows: the terse block counts
447		// failures and sends the reader to doctor. setupComponentFailureDetails is
448		// where the dedup lives, so it is asserted there rather than through a
449		// renderer that never prints a hint at all.
450		_, _, failed := partitionSetupComponents(report.Instant.Components)
451		out := strings.Join(setupComponentFailureDetails(failed, "--", base.SetupBrainBinaryName), "\n")
452	
453		if !strings.Contains(out, "refusing to seed") || !strings.Contains(out, "refusing to index") {
454			t.Fatalf("both failures must still be named, so this guard is not vacuous:\n%s", out)
455		}
456		if n := strings.Count(out, "hint: "); n != 1 {
457			t.Fatalf("one remedy, one appearance; printed %d times:\n%s", n, out)
458		}
459	}
460	
461	// Two DIFFERENT remedies must both still be shown — dedup is not suppression.
462	func TestTwoDifferentRemediesAreBothShown(t *testing.T) {
463		t.Parallel()
464		report := setupReport{
465			Instant: setupPhase{Components: []setupComponent{
466				{Name: "seed", State: "failed", Detail: "a", Hint: "first remedy"},
467				{Name: "semantic", State: "failed", Detail: "b", Hint: "second remedy"},
468			}},
469		}
470		_, _, failed := partitionSetupComponents(report.Instant.Components)
471		out := strings.Join(setupComponentFailureDetails(failed, "--", base.SetupBrainBinaryName), "\n")
472		if n := strings.Count(out, "hint: "); n != 2 {
473			t.Fatalf("distinct remedies must both appear, got %d:\n%s", n, out)
474		}
475	}
476	
477	// A Go error is routinely multi-line: errors.Join concatenates its causes with
478	// a newline, and the memory path joins a deterministic failure with a run
479	// failure before it reaches a `warning: %v` line. Keeping only the lines that
480	// carry the prefix dropped every cause after the first — the same information
481	// loss this re-emission exists to repair, one layer down. Raised as a finding
482	// on this PR, and correct.
483	func TestAMultiLineWarningKeepsItsCauses(t *testing.T) {
484		t.Parallel()
485	
486		got := setupWarningsFrom(bytes.NewBufferString(
487			"warning: memory coordinator could not launch: exec failed\npermission denied\nno such file\n"))
488		if len(got) != 1 {
489			t.Fatalf("expected one warning carrying its causes, got %d: %q", len(got), got)
490		}
491		for _, cause := range []string{"exec failed", "permission denied", "no such file"} {
492			if !strings.Contains(got[0], cause) {
493				t.Errorf("the re-emitted warning lost a cause %q: %s", cause, got[0])
494			}
495		}
496	
497		// A continuation ends at a blank line, so unrelated stderr written after a
498		// warning is not swept into it.
499		sep := setupWarningsFrom(bytes.NewBufferString(
500			"warning: first: a\nb\n\nunrelated progress noise\nwarning: second\n"))
501		if len(sep) != 2 {
502			t.Fatalf("expected two warnings, got %d: %q", len(sep), sep)
503		}
504		if strings.Contains(sep[0], "unrelated progress noise") {
505			t.Errorf("stderr after a blank line was swept into the warning: %s", sep[0])
506		}
507		if sep[1] != "second" {
508			t.Errorf("the second warning was altered: %q", sep[1])
509		}
510	}
511	
512	// TestEveryDirtyUnindexedAxisShipsItsRemedy closes the gap the renderer-only
513	// fix left: an agent reading `status --json` got the diagnosis and no way
514	// out, because only the text surface re-attached the hint.
515	//
516	// It walks the PRODUCERS, so adding a third dirty-unindexed axis without a
517	// remedy fails here rather than silently reaching the JSON consumers.
518	func TestEveryDirtyUnindexedAxisShipsItsRemedy(t *testing.T) {
519		t.Parallel()
520		for _, file := range []string{"semantic.go", "agent_surface.go"} {
521			src := readGoSourceForTest(t, file)
522			rest := src
523			for {
524				i := strings.Index(rest, "State:  dirtyUnindexedAxisState")
525				if i < 0 {
526					i = strings.Index(rest, "State:   dirtyUnindexedAxisState")
527				}
528				if i < 0 {
529					break
530				}
531				// The literal ends at the first line that closes it.
532				end := strings.Index(rest[i:], "\n\t\t\t}")
533				if end < 0 {
534					end = strings.Index(rest[i:], "\n\t\t}")
535				}
536				if end < 0 {
537					end = len(rest) - i
538				}
539				literal := rest[i : i+end]
540				if !strings.Contains(literal, "Remedy:") {
541					t.Errorf("%s: a dirty-unindexed axis ships with no remedy, so `status --json` states a cause and no next step:\n%s", file, literal)
542				}
543				rest = rest[i+end:]
544			}
545		}
546	}
547	
548	// And the JSON side specifically: the field must survive encoding, because
549	// that is the surface the finding was about.
550	func TestTheRemedyReachesTheJSONReport(t *testing.T) {
551		t.Parallel()
552		axis := staleAxis{
553			State:  dirtyUnindexedAxisState,
554			Detail: "semantic index is based on committed HEAD",
555			Remedy: setupDirtyWorktreeHint("entire brain"),
556		}
557		encoded, err := json.Marshal(axis)
558		if err != nil {
559			t.Fatal(err)
560		}
561		var back map[string]any
562		if err := json.Unmarshal(encoded, &back); err != nil {
563			t.Fatal(err)
564		}
565		remedy, _ := back["remedy"].(string)
566		if !strings.Contains(remedy, "--worktree") {
567			t.Fatalf("an agent reading the report gets no next step; remedy=%q in %s", remedy, encoded)
568		}
569		// Additive: a clean axis must not grow an empty key.
570		clean, err := json.Marshal(staleAxis{State: "current"})
571		if err != nil {
572			t.Fatal(err)
573		}
574		if strings.Contains(string(clean), "remedy") {
575			t.Fatalf("remedy must be omitempty so existing readers are unaffected: %s", clean)
576		}
577	}
578	
579	// setupRenderFixtureReport and renderSetupSummaryPlain used to live in
580	// setup_render_test.go, beside the long closing block this PR extended. That
581	// renderer is gone (#401 replaced it with the phase + terse output), so they
582	// are rebuilt here against the CURRENT renderer.
583	//
584	// The point of rebuilding rather than deleting: these tests assert substance,
585	// not layout -- that an unqueryable brain is never called ready, that a
586	// component is called by one name, that a remedy is stated once. Every one of
587	// those claims is still about what a reader sees, and the reader now sees the
588	// terse block. Retargeting keeps the claims; deleting would have dropped them
589	// with the renderer that happened to carry them.
590	func setupRenderFixtureReport() setupReport {
591		return setupReport{
592			SchemaVersion: 1,
593			GeneratedAt:   setupTestNow,
594			Repo:          "/repo",
595			RepoKey:       "gh/demo-org/brain-demo",
596			BrainPath:     "/brain",
597			Instant: setupPhase{
598				State:   "degraded",
599				Seconds: 0.7,
600				Components: []setupComponent{
601					{Name: brainComponentSessions, State: "failed", Detail: "checkpoint_scope_incomplete", Hint: "add a git remote"},
602					{Name: brainComponentSeed, State: "ok"},
603					{Name: brainComponentDocs, State: "ok"},
604					{Name: brainComponentSemantic, State: "ok"},
605				},
606			},
607			Backfill:  setupPhase{State: "skipped", Detail: "--no-backfill"},
608			Workspace: setupWorkspaceState{Name: "default", Registered: true},
609			Daemon:    daemonState{Manager: daemonManagerUnsupported, Detail: "skipped: --no-daemon"},
610			Facts:     factsBackfillStatus{Sessions: 618, Distilled: 300},
611		}
612	}
613	
614	// renderSetupSummaryPlain renders the closing block a reader actually gets, in
615	// plain mode. Queryability is derived from the report rather than passed, so a
616	// test cannot assert "not ready" while handing the renderer a ready flag.
617	func renderSetupSummaryPlain(t *testing.T, report setupReport, timings *setupTimings) string {
618		t.Helper()
619		out := &bytes.Buffer{}
620		theme, _ := tui.ThemeByName("default")
621		queryable := len(setupUnqueryableCore(report.Instant.Components)) == 0
622		terse := terseReportFor(report, timings, queryable, defaultSetupOptions(), base.SetupBrainBinaryName)
623		setupui.RenderTerse(out, setupui.NewRendererWidth(tui.NewRendererWith(theme, tui.PlainCaps()), 200), terse)
624		return out.String()
625	}
626	
627	// TestQueryabilityClauseNeverOverclaims covers the --verbose phase line, which
628	// no other test in this file reaches: renderSetupSummaryPlain derives
629	// queryability itself, and the whole-run test asserts on the error. Removing
630	// the guard left both green, so it is asserted directly here.
631	func TestQueryabilityClauseNeverOverclaims(t *testing.T) {
632		t.Parallel()
633		ok := []setupComponent{{Name: brainComponentSeed, State: "ok"}, {Name: brainComponentSemantic, State: "ok"}}
634		if got := setupQueryabilityClause(ok); !strings.Contains(got, "queryable now") {
635			t.Fatalf("a built core is queryable: %q", got)
636		}
637		none := []setupComponent{
638			{Name: brainComponentSeed, State: "failed", Detail: "dirty_worktree"},
639			{Name: brainComponentSemantic, State: "failed", Detail: "dirty_worktree"},
640		}
641		got := setupQueryabilityClause(none)
642		if strings.Contains(got, "queryable now") {
643			t.Fatalf("no index and no baseline is not queryable: %q", got)
644		}
645		for _, want := range []string{"code index", "seed baseline"} {
646			if !strings.Contains(got, "no "+want) {
647				t.Fatalf("the clause must name what is unavailable (%q): %q", want, got)
648			}
649		}
650	}
