314	// A missing semantic index has two different repairs and only one of them was
315	// ever named: `refresh` rebuilds the index when a graph provider is installed,
316	// but with no provider the same advice sends the reader through an exit that
317	// changes nothing. When the probe reports the provider absent, the next step
318	// must name the install command and only then the index rebuild.
319	func TestStatusNextStepNamesGraphInstallWhenProviderAbsent(t *testing.T) {
320		t.Parallel()
321		h := statusHealth{SemanticMissing: true, SemanticProviderAbsent: true}
322		got := h.nextStepMessage(base.SetupBrainBinaryName)
323		for _, want := range []string{"entire plugin install graph", base.SemanticIndexVerb} {
324			if !strings.Contains(got, want) {
325				t.Fatalf("next step %q does not name %q", got, want)
326			}
327		}
328		if withProvider := (statusHealth{SemanticMissing: true}).nextStepMessage(base.SetupBrainBinaryName); strings.Contains(withProvider, "plugin install") {
329			t.Fatalf("provider-present next step must stay the refresh remedy: %q", withProvider)
330		}
331	}
