313			"unsafe freshness":   {health: statusHealth{Severity: "unsafe"}, want: "refresh --agent none"},
314			"degraded freshness": {health: statusHealth{Severity: "degraded"}, want: "refresh --agent none"},
315			"a health issue":     {health: statusHealth{Issues: 1}, want: "doctor"},
316		} {
