func (r *Renderer) PhaseColor(p Phase) lipgloss.Color {
	theme := r.Theme()
	switch p {
	case PhaseInstant:
		return theme.Link
	case PhaseBackfill:
		return theme.Alt
	case PhaseDaemon:
		return theme.Accent
	case PhaseDone:
		return theme.Good
	case PhaseSkipped:
		return theme.Flag
	case PhaseFailed:
		return theme.Bad
	default:
		return theme.Text
	}
}

// PhasePaint colours s for a phase.
func (r *Renderer) PhasePaint(p Phase, s string) string {
	if p == PhaseNeutral {
		return s
	}
	return r.Paint(r.PhaseColor(p), s)
}

